class LogFormatter {
public:
    enum class Encoding { UTF8, ASCII, LATIN1 };

    static std::string sanitize(const std::string& input, Encoding enc) {
        std::string result;
        result.reserve(input.size());
        for (unsigned char c : input) {
            if (c == '\n' || c == '\r') {
                result += "\\n";
            } else if (c < 0x20 && c != '\t') {
                result += '?';
            } else {
                result.push_back(c);
            }
        }
        return result;
    }

    static std::string normalizeEncoding(const std::string& input, Encoding from, Encoding to) {
        if (from == to) return input;
        std::string result;
        result.reserve(input.size());
        if (from == Encoding::UTF8 && to == Encoding::LATIN1) {
            size_t i = 0;
            while (i < input.size()) {
                unsigned char c = input[i];
                if (c < 0x80) {
                    result.push_back(c);
                    i++;
                } else if ((c & 0xE0) == 0xC0 && i + 1 < input.size()) {
                    // Two-byte UTF-8 sequence -> Latin-1
                    unsigned char c2 = input[i + 1];
                    unsigned int codepoint = ((c & 0x1F) << 6) | (c2 & 0x3F);
                    if (codepoint > 0xFF) {
                        result.push_back('?');
                    } else {
                        result.push_back(static_cast<char>(codepoint & 0xFF));
                    }
                    i += 2;
                } else {
                    result.push_back('?');
                    i++;
                }
            }
        } else {
            result = input;
        }
        // Post-encoding sanitization pass for control characters
        std::string safe;
        safe.reserve(result.size());
        for (unsigned char c : result) {
            if (c == '\n' || c == '\r') {
                safe += "\\n";
            } else if (c < 0x20 && c != '\t') {
                safe += '?';
            } else {
                safe.push_back(c);
            }
        }
        return safe;
    }
};

class AuditLogger {
private:
    std::ofstream logFile_;
    LogFormatter::Encoding storageEncoding_;

    std::string timestamp() {
        time_t now = time(nullptr);
        char buf[64];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", gmtime(&now));
        return std::string(buf);
    }

public:
    AuditLogger(const std::string& path, LogFormatter::Encoding enc = LogFormatter::Encoding::LATIN1)
        : storageEncoding_(enc) {
        logFile_.open(path, std::ios::app);
    }

    void logUpload(const std::string& username, const std::string& filename, size_t size) {
        // Sanitize in UTF-8 first
        std::string safeUser = LogFormatter::sanitize(username, LogFormatter::Encoding::UTF8);
        std::string safeFile = LogFormatter::sanitize(filename, LogFormatter::Encoding::UTF8);

        // Convert to storage encoding
        std::string finalUser = LogFormatter::normalizeEncoding(
            safeUser, LogFormatter::Encoding::UTF8, storageEncoding_);
        std::string finalFile = LogFormatter::normalizeEncoding(
            safeFile, LogFormatter::Encoding::UTF8, storageEncoding_);

        logFile_ << "[" << timestamp() << "] UPLOAD user=" << finalUser
                 << " file=" << finalFile << " size=" << size << std::endl;
    }

    void logAccess(const std::string& username, const std::string& resource) {
        std::string safeUser = LogFormatter::sanitize(username, LogFormatter::Encoding::UTF8);
        std::string safeResource = LogFormatter::sanitize(resource, LogFormatter::Encoding::UTF8);

        std::string finalUser = LogFormatter::normalizeEncoding(
            safeUser, LogFormatter::Encoding::UTF8, storageEncoding_);
        std::string finalResource = LogFormatter::normalizeEncoding(
            safeResource, LogFormatter::Encoding::UTF8, storageEncoding_);

        logFile_ << "[" << timestamp() << "] ACCESS user=" << finalUser
                 << " resource=" << finalResource << std::endl;
    }

    ~AuditLogger() { if (logFile_.is_open()) logFile_.close(); }
};

class UploadService {
private:
    AuditLogger& logger_;
    std::string uploadDir_;
    size_t maxFileSize_;

    bool validateFilename(const std::string& name) {
        if (name.empty() || name.size() > 255) return false;
        if (name.find("..") != std::string::npos) return false;
        if (name[0] == '/' || name[0] == '\\') return false;
        // Reject any embedded path separators to prevent directory traversal / subdir writes.
        if (name.find('/') != std::string::npos) return false;
        if (name.find('\\') != std::string::npos) return false;
        // Reject NUL and other control characters in filenames.
        for (unsigned char c : name) {
            if (c < 0x20 || c == 0x7F) return false;
        }
        return true;
    }

    std::string computeStoragePath(const std::string& filename) {
        auto hash = std::hash<std::string>{}(filename + std::to_string(time(nullptr)));
        return uploadDir_ + "/" + std::to_string(hash) + "_" + filename;
    }

public:
    UploadService(AuditLogger& logger, const std::string& dir, size_t maxSize = 10*1024*1024)
        : logger_(logger), uploadDir_(dir), maxFileSize_(maxSize) {}

    int handleUpload(const std::string& username, const std::string& filename,
                     const std::vector<uint8_t>& data) {
        if (!validateFilename(filename)) {
            return -1;
        }
        if (data.size() > maxFileSize_) {
            return -2;
        }

        std::string storagePath = computeStoragePath(filename);

        std::ofstream out(storagePath, std::ios::binary);
        if (!out.is_open()) return -3;
        out.write(reinterpret_cast<const char*>(data.data()), data.size());
        out.close();

        logger_.logUpload(username, filename, data.size());
        return 0;
    }
};

int main() {
    AuditLogger logger("/var/log/uploads/audit.log");
    UploadService service(logger, "/var/uploads");

    // Simulated request processing
    std::string user = "testuser";
    std::string file = "document.pdf";
    std::vector<uint8_t> content = {0x25, 0x50, 0x44, 0x46};

    int result = service.handleUpload(user, file, content);
    if (result == 0) {
        std::cout << "Upload successful" << std::endl;
    } else {
        std::cout << "Upload failed: " << result << std::endl;
    }
    return 0;
}
